canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;const p=screenPoint(e);if(editSession){editorClick(p);return;}const c=cowAt(p),onComponent=!!editorHit(p);pointer={id:e.pointerId,startX:e.clientX,startY:e.clientY,cow:tool==='move'?c?.i:undefined,moved:false,panning:!onComponent&&!carried,panX:pan.x,panY:pan.y};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointermove',e=>{const p=screenPoint(e);if(editSession){editHover=unproject(p.x,p.y);return;}if(pointer&&pointer.id===e.pointerId&&Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)>5){if(pointer.panning){const r=canvas.getBoundingClientRect(),scale=Math.min(r.width/700,r.height/470)*camera().scale;pan.x=Math.max(-450,Math.min(450,pointer.panX+(e.clientX-pointer.startX)/scale));pan.y=Math.max(-300,Math.min(300,pointer.panY+(e.clientY-pointer.startY)/scale));pointer.moved=true;canvas.style.cursor='grabbing';return;}if(tool==='move'&&pointer.cow!==undefined){if(!pointer.moved){pickCow(pointer.cow);pointer.moved=true;}const w=unproject(p.x,p.y+12);if(carried){carried.x=w.x;carried.y=w.y;}}}else if(tool==='move'&&carried&&!pointer){const w=unproject(p.x,p.y);carried.x=w.x;carried.y=w.y;}else if(!pointer)canvas.style.cursor=cowAt(p)?(tool==='move'?'grab':'pointer'):'default';});
