// Care props stay anchored to the cow while all other idle motion is suspended.
function drawCowActivity(c,i,p,time){
 const a=cowActions.get(c),face=i%2?-1:1;
 if(c.sleeping){g.save();g.font='bold 10px monospace';g.textAlign='center';for(let j=0;j<3;j++){const u=(time*.32+j/3)%1;g.globalAlpha=Math.sin(u*Math.PI)*.85;g.fillStyle='#faf3d8';g.fillText(j?'z':'Z',p[0]+8+u*10,p[1]-23-u*22);}g.restore();return;}
 if(!a)return;const u=actionProgress(a);
 if(a.type==='feed'){const x=p[0]+face*25,y=p[1]+2;
 ellipse(x,y+3,11,3,'#26382330');poly([[x-10,y-2],[x+10,y-2],[x+7,y+5],[x-7,y+5]],'#88623e');ellipse(x,y-2,10,3,'#c79c63');ellipse(x,y-2,8,2,'#6b5134');
 const remaining=Math.ceil((1-u)*24);for(let k=0;k<remaining;k++){const xx=x+(hash(k,51)-.5)*15,yy=y-3-hash(k,52)*(1-u)*5;line([xx,yy],[xx+3,yy-1],k%2?'#ddc36c':'#bca64f');}
 if(u<.9){const chew=Math.sin(time*10);g.fillStyle='#d6bd69';g.fillRect(p[0]+face*23,p[1]-4+chew,2,1);}
 }else{const x=p[0]-face*8,y=p[1]+8;
 ellipse(x+1,y+1,9,2,'#26382325');g.save();g.translate(Math.round(x),Math.round(y));
 // Glass jug with a handle, visible empty volume and rising cream-colored milk.
 g.strokeStyle='#aabdb6';g.lineWidth=1;g.strokeRect(5,-12,4,7);poly([[-5,0],[5,0],[6,-10],[3,-14],[3,-17],[-3,-17],[-3,-14],[-6,-10]],'#93afa888');
 const fill=Math.max(1,Math.round(u*12));g.fillStyle='#faf1d4';g.fillRect(-4,-fill,8,fill);g.fillStyle='#fffbe9';g.fillRect(-3,-fill,6,1);line([-4,-15],[3,-15],'#d8e5d8');line([-5,-10],[-5,-2],'#deeee0');g.restore();
 if(u<.95){g.fillStyle='#fff4d9';g.fillRect(x-1,y-20+(time*26%5),1,3);}
 }
}
function bakeIslandBase(surface){
 islandCtx.clearRect(0,0,1800,1000);const base=islandCtx.createImageData(1800,1000),src=surface.data,out=base.data,depth=34;
 for(let x=170;x<1630;x++){let edge=-1;for(let y=889;y>=85;y--)if(src[(y*1800+x)*4+3]){edge=y;break;}if(edge<0)continue;
 for(let d=0;d<depth;d++){const y=edge+d;if(y>=1000)break;const n=hash(x,y),stratum=Math.floor(d/6),shadeSide=x<900?1:.82,band=Math.sin(x*.035+stratum*1.3)*2,grain=(n-.5)*23,root=d<4;
 const color=root?[65,84,61]:d<14?[126+band,100+band,72]:[77+band,86+band,97];const k=(y*1800+x)*4;
 out[k]=color[0]*shadeSide+grain;out[k+1]=color[1]*shadeSide+grain;out[k+2]=color[2]*shadeSide+grain;out[k+3]=d>31&&n>.65?0:255;
 if(!root&&n>.96){out[k]+=24;out[k+1]+=22;out[k+2]+=19;}const seam=(x+Math.floor(d/8)*7+Math.floor(hash(Math.floor(x/15),Math.floor(d/8))*3))%15;if(d%8===0||seam===0){out[k]-=26;out[k+1]-=25;out[k+2]-=23;}else if(d%8===1){out[k]+=17;out[k+1]+=17;out[k+2]+=14;}
 }}islandCtx.putImageData(base,0,0);
}
function drawCloudShadows(time){if(ambientLight.day<.02)return;g.save();g.globalCompositeOperation='source-atop';g.globalAlpha=ambientLight.day*(state.weather===0?.11:.17);const b=bounds(),p=proj((b.xmin+b.xmax)/2,(b.ymin+b.ymax)/2),span=((b.xmax-b.xmin)+(b.ymax-b.ymin))*17;
 for(let j=0;j<3;j++){const x=p[0]-span*.8+((time*5+j*span*.58)%(span*1.8)),y=p[1]-60+j*55;for(let k=0;k<3;k++){g.save();g.translate(x+k*30,y+Math.sin(k*2)*8);g.scale(1,.36);const grad=g.createRadialGradient(0,0,0,0,0,85);grad.addColorStop(0,'#263a2a');grad.addColorStop(.55,'#263a2a80');grad.addColorStop(1,'#263a2a00');g.fillStyle=grad;g.fillRect(-85,-85,170,170);g.restore();}}g.restore();}
let birdFlight=null,nextBirdAt=8+Math.random()*18;
function drawBirds(time){if(editSession||state.weather===3||state.weather===4||state.weather===6||ambientLight.day<.15)return;
 if(!birdFlight&&time>=nextBirdAt){const b=bounds(),p=proj((b.xmin+b.xmax)/2,(b.ymin+b.ymax)/2);birdFlight={start:time,y:p[1]-100,reverse:Math.random()>.5,count:2+Math.floor(Math.random()*3)};nextBirdAt=time+35+Math.random()*45;}
 if(!birdFlight)return;const f=birdFlight,u=(time-f.start)/13;if(u>1){birdFlight=null;return;}for(let j=0;j<f.count;j++){const x=(f.reverse?1-u:u)*850-75-j*13,y=f.y+Math.sin(u*4)*14+j*7,wing=Math.sin(time*8+j*1.7)*3;line([x-5,y-wing],[x,y+1],'#394838',1);line([x,y+1],[x+5,y-wing],'#394838',1);g.fillStyle='#4c5846';g.fillRect(x,y,2,2);}}

function cowNeeds(c){const needs=[];if(c.food<35)needs.push({icon:'♧',label:'Hungry',color:'#dfbc6d'});if(!c.sleeping&&(c.energy??80)<30)needs.push({icon:'☾',label:'Sleepy',color:'#b5c2e1'});if(c.love<40)needs.push({icon:'♡',label:'Bored · needs affection',color:'#dfa2ad'});if(c.sleeping)needs.push({icon:'z',label:'Sleeping',color:'#b5c2e1'});else if(c.ready<=Date.now()&&c.food>=25&&(c.energy??80)>=15&&!cowActions.has(c))needs.push({icon:'♙',label:'Ready to milk',color:'#ebdfbc'});return needs;}
function selectCow(i){selectedCow=state.cows[i];renderCowInfo();}
function renderCowInfo(){const card=$('#cow-info');if(!card)return;const c=selectedCow,i=state.cows.indexOf(c);card.hidden=!c||i<0||!!editSession||currentScreen!=='farm';if(card.hidden)return;const needs=cowNeeds(c),cool=Math.max(0,Math.ceil((c.ready-Date.now())/1000)),a=cowActions.get(c),mood=c.sleeping?'Resting and recovering':a?(a.type==='feed'?'Enjoying hay':'Milking in progress'):needs.length?needs.map(n=>n.label).join(' · '):'Happy and comfortable';
 const signature=[i,c.name,c.breed,Math.round(c.food),Math.round(c.energy??80),Math.round(c.love),cool,mood].join('|');if(card.dataset.signature===signature)return;card.dataset.signature=signature;
 card.innerHTML='<button class="cow-info-close" aria-label="Close cow stats">×</button><b>'+esc(c.name)+'</b><small>'+breeds[c.breed][0]+'</small><div class="cow-info-bars">'+[['♧ Fullness',c.food],['☾ Energy',c.energy??80],['♡ Affection',c.love]].map(([label,value])=>'<div><span>'+label+'</span><strong>'+Math.round(value)+'%</strong><div class="bar"><div style="width:'+value+'%"></div></div></div>').join('')+'</div><p>'+esc(mood)+'</p><div class="milk-status">♙ '+(cool?'Milk ready in '+cool+'s':c.sleeping?'Wake to milk':c.food<25?'Feed before milking':(c.energy??80)<15?'Rest before milking':'Milk is ready')+'</div><div class="cow-quick-actions"><button data-care="pet">♡ Pet</button><button data-care="feed">♧ Feed</button><button data-care="milk">♙ Milk</button><button data-care="sleep">'+(c.sleeping?'☀ Wake':'☾ Sleep')+'</button></div>';
 card.querySelector('.cow-info-close').onclick=()=>{selectedCow=null;card.hidden=true;};card.querySelectorAll('[data-care]').forEach(b=>b.onclick=()=>({pet,feed,milk,sleep}[b.dataset.care])(i));
}
function drawCowNeeds(c,p,time){const needs=cowNeeds(c).slice(0,3);needs.forEach((n,j)=>{const x=p[0]+(j-(needs.length-1)/2)*15,y=p[1]-40+(motionPaused?0:Math.sin(time*1.8)*.7);ellipse(x,y+1,6.7,6.7,'#34434a');ellipse(x,y,6,6,n.color);g.font='9px monospace';g.textAlign='center';g.fillStyle='#35434a';g.fillText(n.icon,x,y+3);});}
